import { SessionData, SessionStore } from './store';

export interface MemorySessionStoreEntry {
  data: SessionData;
  expiresAt: number;
}

export class MemorySessionStore implements SessionStore {
  private sessions = new Map<string, MemorySessionStoreEntry>();

  private nowMs(): number {
    return Date.now();
  }

  private cleanupIfExpired(sessionId: string): boolean {
    const entry = this.sessions.get(sessionId);
    if (!entry) return true;
    if (entry.expiresAt <= this.nowMs()) {
      this.sessions.delete(sessionId);
      return true;
    }
    return false;
  }

  async get(sessionId: string): Promise<SessionData | null> {
    if (this.cleanupIfExpired(sessionId)) return null;
    const entry = this.sessions.get(sessionId)!;
    return { ...entry.data };
  }

  async set(sessionId: string, data: SessionData, ttlSec: number): Promise<void> {
    const expiresAt = this.nowMs() + ttlSec * 1000;
    this.sessions.set(sessionId, { data: { ...data }, expiresAt });
  }

  async delete(sessionId: string): Promise<void> {
    this.sessions.delete(sessionId);
  }

  async touch(sessionId: string, ttlSec: number): Promise<void> {
    const entry = this.sessions.get(sessionId);
    if (!entry) return;
    entry.expiresAt = this.nowMs() + ttlSec * 1000;
    entry.data.lastAccess = this.nowMs();
  }
}
