import { randomUUID } from 'node:crypto';
import { SessionData, SessionStore } from '@/sessions/store';

export async function createCsrfToken(sessionId: string, store: SessionStore): Promise<string> {
  const token = randomUUID();
  const session = await store.get(sessionId) ?? { createdAt: Date.now(), lastAccess: Date.now() };
  session.csrfToken = token;
  await store.set(sessionId, session, 7 * 24 * 60 * 60); // 7 days
  return token;
}

export async function verifyCsrfToken(session: SessionData | undefined | null, token: string | undefined): Promise<boolean> {
  if (!session || !session.csrfToken || !token) return false;
  // Constant-time comparison to prevent timing attacks
  const a = Buffer.from(session.csrfToken);
  const b = Buffer.from(token);
  if (a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) {
    result |= a[i] ^ b[i];
  }
  return result === 0;
}
```

