import { Request, Response, Router } from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { hashPassword, verifyPassword, passwordSchema } from '@/services/auth/password';
import { createCsrfToken } from '@/services/auth/csrf';
import { prisma } from '@/lib/prisma';
import { requireAuth } from '@/middleware/auth';
import { SessionStore } from '@/sessions/store';

const router = Router();

const registerSchema = z.object({
  email: z.string().email(),
  password: passwordSchema,
  name: z.string().min(1).max(100),
});

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

const SESSION_TTL_SECONDS = 7 * 24 * 60 * 60;
const SESSION_COOKIE_NAME = 'sid';
const CSRF_COOKIE_NAME = 'csrf-token';

function cookieOptions(maxAgeMs: number) {
  return {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
    maxAge: maxAgeMs,
    path: '/',
  };
}

function csrfCookieOptions(maxAgeMs: number) {
  return {
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
    maxAge: maxAgeMs,
    path: '/',
  };
}

function getStore(req: Request): SessionStore {
  return req.app.locals.sessionStore as SessionStore;
}

function getSid(req: Request): string | undefined {
  return req.cookies[SESSION_COOKIE_NAME];
}

async function upsertSession(req: Request, store: SessionStore, userId?: string, existingSid?: string): Promise<string> {
  const sid = existingSid ?? randomUUID();
  const now = Date.now();
  const session = (await store.get(sid)) ?? { createdAt: now, lastAccess: now };
  if (userId) session.userId = userId;
  await store.set(sid, session, SESSION_TTL_SECONDS);
  return sid;
}

router.post('/register', async (req: Request, res: Response) => {
  const parse = registerSchema.safeParse(req.body);
  if (!parse.success) {
    res.status(400).json({ error: parse.error.errors[0].message });
    return;
  }

  const { email, password, name } = parse.data;
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) {
    res.status(409).json({ error: '이미 가입된 이메일입니다.' });
    return;
  }

  const passwordHash = await hashPassword(password);
  const user = await prisma.user.create({
    data: { email, password: passwordHash, name },
    select: { id: true, email: true, name: true },
  });

  const sid = await upsertSession(req, getStore(req), user.id, getSid(req));
  await createCsrfToken(sid, getStore(req));

  const session = await getStore(req).get(sid);
  res.cookie(SESSION_COOKIE_NAME, sid, cookieOptions(SESSION_TTL_SECONDS * 1000));
  res.cookie(CSRF_COOKIE_NAME, session?.csrfToken ?? '', csrfCookieOptions(SESSION_TTL_SECONDS * 1000));
  res.status(201).json({ user });
});

