import http from 'node:http';
import type { Express } from 'express';

export class TestClient {
  private baseUrl: string;
  public cookies: Record<string, string | null> = {};
  public csrfToken?: string;

  constructor(port: number) {
    this.baseUrl = `http://127.0.0.1:${port}`;
  }

  parseCookies(res: Response): void {
    const setCookies = res.headers.getSetCookie?.() ?? [];
    for (const c of setCookies) {
      const [pair] = c.split(';');
      const [name, ...rest] = pair.split('=');
      const value = rest.join('=').trim();
      if (name && value) {
        this.cookies[name.trim()] = decodeURIComponent(value);
      } else if (name) {
        this.cookies[name.trim()] = null;
      }
    }
    if (this.cookies['csrf-token']) this.csrfToken = this.cookies['csrf-token'] as string;
  }

  cookieHeader(): string {
    return Object.entries(this.cookies)
      .filter(([, v]) => v !== null)
      .map(([k, v]) => `${k}=${encodeURIComponent(v as string)}`)
      .join('; ');
  }

  async request(method: string, path: string, body?: unknown): Promise<Response> {
    const headers: Record<string, string> = {};
    if (method !== 'GET' && this.csrfToken) {
      headers['X-CSRF-Token'] = this.csrfToken;
    }
    if (body !== undefined) headers['Content-Type'] = 'application/json';
    const cookie = this.cookieHeader();
    if (cookie) headers['Cookie'] = cookie;
    return fetch(`${this.baseUrl}${path}`, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
    });
  }
}

export async function startServer(app: Express): Promise<{ server: http.Server; port: number }> {
  const server = http.createServer(app);
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const address = server.address();
  const port = typeof address === 'object' && address ? address.port : 0;
  return { server, port };
}
