import { SessionData } from '@/sessions/store'

declare global {
  namespace Express {
    interface Request {
      user?: { id: string }
      session?: SessionData
    }
  }
}

export {}

export interface SessionData {
  userId?: string
  csrfToken?: string
  createdAt: number
  lastAccess: number
}

export interface SessionStore {
  get(sessionId: string): Promise<SessionData | null>
  set(sessionId: string, data: SessionData, ttlSec: number): Promise<void>
  delete(sessionId: string): Promise<void>
  touch(sessionId: string, ttlSec: number): Promise<void>
}

import { SessionData, SessionStore } from './store'

interface Entry {
  data: SessionData
  expiresAt: number
}

export class MemorySessionStore implements SessionStore {
  private sessions = new Map<string, Entry>()

  private now(): number {
    return Date.now()
  }

  private cleanup(sessionId: string): boolean {
    const entry = this.sessions.get(sessionId)
    if (!entry) return true
    if (entry.expiresAt <= this.now()) {
      this.sessions.delete(sessionId)
      return true
    }
    return false
  }

  async get(sessionId: string): Promise<SessionData | null> {
    if (this.cleanup(sessionId)) return null
    const entry = this.sessions.get(sessionId)!
    return { ...entry.data }
  }

  async set(sessionId: string, data: SessionData, ttlSec: number): Promise<void> {
    this.sessions.set(sessionId, {
      data: { ...data },
      expiresAt: this.now() + ttlSec * 1000,
    })
  }

  async delete(sessionId: string): Promise<void> {
    this.sessions.delete(sessionId)
  }

  async touch(sessionId: string, ttlSec: number): Promise<void> {
    const entry = this.sessions.get(sessionId)
    if (!entry) return
    if (entry.expiresAt <= this.now()) {
      this.sessions.delete(sessionId)
      return
    }
    entry.expiresAt = this.now() + ttlSec * 1000
    entry.data.lastAccess = this.now()
  }

  clear(): void {
    this.sessions.clear()
  }
}

import argon2 from 'argon2'
import { z } from 'zod'

const ARGON2_OPTIONS = {
  type: argon2.argon2id,
  memoryCost: 19456,
  timeCost: 2,
  parallelism: 1,
}

export async function hashPassword(plain: string): Promise<string> {
  return argon2.hash(plain, ARGON2_OPTIONS)
}

export async function verifyPassword(hash: string, plain: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, plain)
  } catch {
    return false
  }
}

export const passwordSchema = z
  .string()
  .min(8, '비밀번호는 최소 8자 이상이어야 합니다.')
  .max(128, '비밀번호는 최대 128자 이하여야 합니다.')
  .regex(/[A-Za-z]/, '비밀번호에 영문이 1자 이상 포함되어야 합니다.')
  .regex(/[0-9]/, '비밀번호에 숫자가 1자 이상 포함되어야 합니다.')

import { randomUUID } from 'node:crypto'
import { SessionData, SessionStore } from '@/sessions/store'

const SESSION_TTL_SECONDS = 7 * 24 * 60 * 60

export async function createCsrfToken(sessionId: string, store: SessionStore): Promise<string> {
  const token = randomUUID()
  const session = (await store.get(sessionId)) ?? {
    createdAt: Date.now(),
    lastAccess: Date.now(),
  }
  session.csrfToken = token
  await store.set(sessionId, session, SESSION_TTL_SECONDS)
  return token
}

export async function verifyCsrfToken(
  session: SessionData | undefined,
  token: string | undefined,
): Promise<boolean> {
  if (!session?.csrfToken || !token) return false
  const a = Buffer.from(session.csrfToken)
  const b = Buffer.from(token)
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i]
  }
  return diff === 0
}

import { Request, Response, NextFunction } from 'express'
import { SessionStore } from '@/sessions/store'

const COOKIE_NAME = 'sid'
const TTL_SECONDS = 7 * 24 * 60 * 60

function getStore(req: Request): SessionStore {
  return req.app.locals.sessionStore as SessionStore
}

export async function authMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): Promise<void> {
  try {
    const sid = req.cookies[COOKIE_NAME]
    if (!sid) return next()

    const store = getStore(req)
    const session = await store.get(sid)
    if (session) {
      req.session = session
      if (session.userId) {
        req.user = { id: session.userId }
      }
      await store.touch(sid, TTL_SECONDS)
    }
    next()
  } catch (e) {
    next(e)
  }
}

export function requireAuth(req: Request, res: Response, next: NextFunction): void {
  if (!req.user) {
    res.status(401).json({ error: '인증이 필요합니다.' })
    return
  }
  next()
}

import { Request, Response, NextFunction } from 'express'
import { verifyCsrfToken } from '@/services/auth/csrf'

const MUTATION_METHODS = new Set(['POST', 'PUT', 'DELETE'])

export async function csrfMiddleware(
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> {
  if (!MUTATION_METHODS.has(req.method)) return next()

  try {
    const ok = await verifyCsrfToken(
      req.session,
      req.headers['x-csrf-token'] as string | undefined,
    )
    if (ok) return next()
    res.status(403).json({ error: 'CSRF 토큰이 누락되었거나 올바르지 않습니다.' })
  } catch (e) {
    next(e)
  }
}

import { Request, Response, NextFunction, Router } from 'express'
import { randomUUID } from 'node:crypto'
import { z } from 'zod'
import { hashPassword, verifyPassword, passwordSchema } from '@/services/auth/password'
import { createCsrfToken } from '@/services/auth/csrf'
import { prisma } from '@/lib/prisma'
import { SessionStore } from '@/sessions/store'
import { requireAuth } from '@/middleware/auth'

const router = Router()

const TTL_SECONDS = 7 * 24 * 60 * 60

const registerSchema = z.object({
  email: z.string().email('유효한 이메일을 입력하세요.'),
  password: passwordSchema,
  name: z.string().min(1, '이름을 입력하세요.').max(100, '이름은 100자 이하로 입력하세요.'),
})

const loginSchema = z.object({
  email: z.string().email('유효한 이메일을 입력하세요.'),
  password: z.string().min(1, '비밀번호를 입력하세요.'),
})

function getStore(req: Request): SessionStore {
  return req.app.locals.sessionStore as SessionStore
}

function getSid(req: Request): string | undefined {
  return req.cookies.sid
}

function sessionCookieOptions() {
  return {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
    maxAge: TTL_SECONDS * 1000,
    path: '/',
  }
}

function csrfCookieOptions() {
  return {
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
    maxAge: TTL_SECONDS * 1000,
    path: '/',
  }
}

type AsyncHandler = (req: Request, res: Response, _next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

router.post(
  '/register',
  asyncRoute(async (req, res) => {
    const parsed = registerSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const { email, password, name } = parsed.data
    const existing = await prisma.user.findUnique({ where: { email } })
    if (existing) {
      res.status(409).json({ error: '이미 가입된 이메일입니다.' })
      return
    }

    const hash = await hashPassword(password)
    const user = await prisma.user.create({
      data: { email, password: hash, name },
      select: { id: true, email: true, name: true },
    })

    const sid = getSid(req) ?? randomUUID()
    await createCsrfToken(sid, getStore(req))
    const session = (await getStore(req).get(sid))!
    session.userId = user.id
    session.lastAccess = Date.now()
    await getStore(req).set(sid, session, TTL_SECONDS)

    res.cookie('sid', sid, sessionCookieOptions())
    res.cookie('csrf-token', session.csrfToken!, csrfCookieOptions())
    res.status(201).json({ user })
  }),
)

router.post(
  '/login',
  asyncRoute(async (req, res) => {
    const parsed = loginSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const { email, password } = parsed.data
    const user = await prisma.user.findUnique({ where: { email } })
    if (!user || !(await verifyPassword(user.password, password))) {
      res.status(401).json({ error: '이메일 또는 비밀번호가 올바르지 않습니다.' })
      return
    }

    const sid = getSid(req) ?? randomUUID()
    await createCsrfToken(sid, getStore(req))
    const session = (await getStore(req).get(sid))!
    session.userId = user.id
    session.lastAccess = Date.now()
    await getStore(req).set(sid, session, TTL_SECONDS)

    res.cookie('sid', sid, sessionCookieOptions())
    res.cookie('csrf-token', session.csrfToken!, csrfCookieOptions())
    res.json({
      user: { id: user.id, email: user.email, name: user.name },
    })
  }),
)

router.post(
  '/logout',
  requireAuth,
  asyncRoute(async (req, res) => {
    const sid = getSid(req)
    if (sid) {
      await getStore(req).delete(sid)
    }
    res.clearCookie('sid', { httpOnly: true, sameSite: 'lax', path: '/' })
    res.clearCookie('csrf-token', { sameSite: 'lax', path: '/' })
    res.json({ ok: true })
  }),
)

router.get(
  '/me',
  requireAuth,
  asyncRoute(async (req, res) => {
    if (!req.user?.id) {
      res.status(401).json({ error: '인증이 필요합니다.' })
      return
    }
    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      select: { id: true, email: true, name: true },
    })
    if (!user) {
      res.status(401).json({ error: '사용자를 찾을 수 없습니다.' })
      return
    }
    res.json({ user })
  }),
)

router.get(
  '/csrf-token',
  asyncRoute(async (req, res) => {
    const store = getStore(req)
    const sid = getSid(req) ?? randomUUID()
    const token = await createCsrfToken(sid, store)
    res.cookie('sid', sid, sessionCookieOptions())
    res.cookie('csrf-token', token, csrfCookieOptions())
    res.json({ csrfToken: token })
  }),
)

export default router

