    const req: any = {
      cookies: {},
      app: { locals: { sessionStore: new MemorySessionStore() } },
    }
    const res: any = createRes()
    const next = vi.fn()
    await authMiddleware(req, res, next)
    expect(req.user).toBeUndefined()
    expect(next).toHaveBeenCalled()
  })
})

